{
  "infotainment con énfasis en figuras públicas": {
    "definicion": "Formato mediático que combina información con entretenimiento, centrándose en la vida, opiniones o actos de personalidades conocidas para atraer la atención. Prioriza el atractivo emocional sobre la profundidad analítica, usando humor, dramatización o narrativas sensacionalistas para presentar datos, a menudo simplificando o distorsionando la realidad.",
    "ejemplo": "Programa de televisión de 2024 que cubrió la visita del presidente a una fábrica de coches, enfocándose en sus bromas y gestos, mientras minimizaba datos técnicos sobre la producción y los retos medioambientales.",
    "como_detectarla": [
      "1. Identifica si el contenido dedica más tiempo a la personalidad del protagonista que a la información factual.",
      "2. Analiza el tono: busca humor, dramatización o elementos sensacionalistas que sustituyen el análisis objetivo.",
      "3. Verifica la proporción entre datos verificables y anécdotas personales; un alto desequilibrio indica infotainment."
    ]
  },
  "omisión de tema relevante": {
    "definicion": "Estrategia comunicativa que excluye deliberadamente información importante o contextual que podría alterar la percepción del público. Se trata de una forma sutil de sesgo que mantiene la narrativa focalizada mientras silencia datos que podrían contradecirla o complicarla.",
    "ejemplo": "Artículo de prensa de marzo 2024 sobre la reforma fiscal que omitió mencionar el aumento del IVA a productos básicos, pese a que era un punto central del proyecto de ley.",
    "como_detectarla": [
      "1. Compila fuentes alternativas sobre el mismo asunto y compara los puntos cubiertos.",
      "2. Busca preguntas frecuentes o críticas que no aparecen en el texto original.",
      "3. Evalúa si la ausencia de ciertos datos cambia significativamente la conclusión del mensaje."
    ]
  },
  "framing de conflicto político en lugar de tecnológico": {
    "definicion": "Reencuadre de una cuestión cuya raíz es tecnológica, presentándola como un enfrentamiento político. El objetivo es polarizar la audiencia y desviar la discusión de aspectos técnicos hacia lealtades partidarias.",
    "ejemplo": "Cobertura de junio 2024 sobre la implementación de redes 5G, donde los medios destacaron la oposición de ciertos partidos a la infraestructura, ignorando los debates sobre seguridad y rendimiento técnico.",
    "como_detectarla": [
      "1. Identifica el tema central (tecnología) y revisa si los titulares y subtítulos destacan disputas partidistas.",
      "2. Examina la distribución del espacio: ¿se dedica más espacio a declaraciones políticas que a explicaciones técnicas?",
      "3. Contrasta con análisis especializados que traten el aspecto tecnológico para detectar desviaciones de enfoque."
    ]
  },
  "omisión deliberada del tema de IA": {
    "definicion": "Acción intencional de excluir cualquier referencia a la inteligencia artificial en la discusión de un asunto donde su presencia es relevante, con el fin de evitar alarmas, controversias o responsabilidad moral.",
    "ejemplo": "Reportaje de agosto 2024 sobre la automatización de procesos en una gran cadena de supermercados, que habló solo de eficiencia operativa sin mencionar que se emplean sistemas de IA para predicción de demanda.",
    "como_detectarla": [
      "1. Detecta si el proceso descrito involucra datos, algoritmos o automatización avanzada.",
      "2. Busca menciones de tecnologías específicas en documentos técnicos o comunicados oficiales que no aparecen en el artículo.",
      "3. Pregunta explícitamente por la presencia de IA; la ausencia de respuesta o evasión indica posible omisión deliberada."
    ]
  },
  "enfoque selectivo en controversias políticas": {
    "definicion": "Selección parcial de eventos o argumentos políticos que generan conflicto, mientras se descartan otros que podrían equilibrar la visión. Sirve para reforzar una narrativa o agenda específica, enfatizando la polarización.",
    "ejemplo": "Programa de debate de septiembre 2024 que sólo analizó los escándalos de corrupción del gobierno de turno, sin cubrir los avances legislativos ni las críticas de la oposición.",
    "como_detectarla": [
      "1. Lista los hechos relevantes del tema y verifica cuántos aparecen en el contenido.",
      "2. Analiza la distribución de tiempo o espacio entre críticas y elogios; una disparidad marcada sugiere selectividad.",
      "3. Consulta fuentes neutrales o de diferentes tendencias para identificar los elementos omitidos."
    ]
  }
}
